#!/usr/bin/env bash
# =====================================================================
# export-ipblocks.sh
# Render the ipblocks-ua-qs source lists as one JSON document.
#
# The sources are plain text: one entry per line, `#` starts a comment,
# blank lines are ignored. Output is deterministic — sorted, de-duplicated
# and without a timestamp — so a regenerated file can be diffed.
#
# Usage:
#   bin/export-ipblocks.sh [output.json]
#
# Default output: website/static/data/ipblocks-ua-qs.json, which the docs
# build publishes at /data/ipblocks-ua-qs.json.
# =====================================================================

set -o pipefail

SCRIPT_DIR=$( cd -- "$( dirname -- "${BASH_SOURCE[0]}" )" &> /dev/null && pwd )
REPO_DIR=$(dirname "$SCRIPT_DIR")
SRC_DIR="$REPO_DIR/ipblocks-ua-qs"
OUTPUT="${1:-$REPO_DIR/website/static/data/ipblocks-ua-qs.json}"

if ! command -v jq >/dev/null 2>&1; then
    echo "error: jq is required" >&2
    exit 1
fi

if [[ ! -d "$SRC_DIR" ]]; then
    echo "error: source directory not found: $SRC_DIR" >&2
    exit 1
fi

# Print one source file as sorted, de-duplicated entries.
read_list() {
    local file="$1"
    [[ -f "$file" ]] || return 0
    LC_ALL=C sed -e 's/#.*//' -e 's/[[:space:]]*$//' -e 's/^[[:space:]]*//' "$file" \
        | LC_ALL=C sed '/^$/d' \
        | LC_ALL=C sort -u
}

as_json_array() {
    jq -R . | jq -s 'map(select(length > 0))'
}

blogvault=$(read_list "$SRC_DIR/ips-blogvault.txt")
umbrella=$(read_list "$SRC_DIR/ips-wp-umbrella.txt")
user_agents=$(read_list "$SRC_DIR/user-agents.txt")
query_strings=$(read_list "$SRC_DIR/query-strings.txt")

all_addresses=$(
    printf '%s\n%s\n' "$blogvault" "$umbrella" \
        | LC_ALL=C sed '/^$/d' \
        | LC_ALL=C sort -u
)

# Anything with a colon or a slash is a network (IPv6 or CIDR); the rest are
# plain addresses a rule can drop straight into `ip.src in { ... }`.
ips=$(printf '%s\n' "$all_addresses" | LC_ALL=C grep -vE '[:/]' || true)
networks=$(printf '%s\n' "$all_addresses" | LC_ALL=C grep -E '[:/]' || true)

asns=$(
    [[ -f "$SRC_DIR/asn.txt" ]] || printf '\n'
    LC_ALL=C sed -e 's/[[:space:]]*$//' -e '/^[[:space:]]*$/d' "$SRC_DIR/asn.txt" 2>/dev/null
)

mkdir -p "$(dirname "$OUTPUT")"

jq -n \
    --argjson blogvault "$(printf '%s\n' "$blogvault" | as_json_array)" \
    --argjson umbrella "$(printf '%s\n' "$umbrella" | as_json_array)" \
    --argjson user_agents "$(printf '%s\n' "$user_agents" | as_json_array)" \
    --argjson query_strings "$(printf '%s\n' "$query_strings" | as_json_array)" \
    --argjson ips "$(printf '%s\n' "$ips" | as_json_array)" \
    --argjson networks "$(printf '%s\n' "$networks" | as_json_array)" \
    --argjson asns "$(printf '%s\n' "$asns" | as_json_array)" \
    '{
        schema_version: 1,
        name: "ipblocks-ua-qs",
        description: "IP, network, user-agent and query-string allowlist sources from the v2 rule era. Regenerated by bin/export-ipblocks.sh; profiles/default.json remains the authority for what ships.",
        source_dir: "ipblocks-ua-qs/",
        sources: [
            "ipblocks-ua-qs/asn.txt",
            "ipblocks-ua-qs/ips-blogvault.txt",
            "ipblocks-ua-qs/ips-wp-umbrella.txt",
            "ipblocks-ua-qs/query-strings.txt",
            "ipblocks-ua-qs/user-agents.txt"
        ],
        ips: $ips,
        networks: $networks,
        asns: ($asns | map(capture("^(?<asn>[0-9]+)\\s*(?:#\\s*(?<label>.*))?$")
                          | { asn: (.asn | tonumber), label: (.label // "") })),
        lists: {
            ips_blogvault: $blogvault,
            ips_wp_umbrella: $umbrella,
            user_agents: $user_agents,
            query_strings: $query_strings
        }
    }' > "$OUTPUT"

echo "wrote $OUTPUT"
